  xf_apply(60);
  ASSERT_EQ(xf_value(), 60);
  ASSERT_EQ(xf_phase(), 0);
  ASSERT_EQ(xf_red_level(), 90);
  ASSERT_EQ(xf_green_level(), 60);
}

